// The poll loop: when to ask, what to keep, when to notify. Everything that
// touches the engine comes in through `deps`, so tests run it on a fake clock.
import {
  attemptStartedAt,
  inFlight,
  startedByPerson,
  transitions,
  visible,
  withPrs,
  type Holds,
  type Pr,
  type Run,
} from "../core/workflow-run.ts";
import { finishedToasts, startedToast } from "../core/run-labels.ts";

type PollerConfig = Holds & {
  activeMs: number; // interval while a run is in flight or a push is waiting
  idleMs: number; // interval while nothing is happening
  watchMs: number; // how long a push keeps the active pace
};

export const DEFAULT_CONFIG: PollerConfig = {
  activeMs: 15_000,
  idleMs: 60_000,
  holdMs: 5 * 60_000,
  failedHoldMs: 30 * 60_000,
  watchMs: 6 * 60_000,
};

const CLOCK_SKEW_MS = 10_000; // the local clock against GitHub's

type Timer = { cancel: () => void };

export type PollerDeps = {
  listRuns: () => Promise<Run[]>;
  listPrs: () => Promise<Pr[]>; // may fail: runs then show no #N
  now: () => number;
  after: (ms: number, callback: () => void) => Timer;
  onChange: () => void; // the band needs a redraw
  toast: (text: string, timeoutMs?: number) => void;
  log: (text: string) => void;
};

export type Poller = {
  start: () => void;
  wake: () => void; // a push happened: look now and keep the active pace
  refresh: () => void; // look now, at the pace the result calls for; no push, so no waiting
  rows: () => Run[];
  waitingSince: () => number | null; // when the push happened, while no run has shown up
  live: () => boolean; // something on the band is counting up: a run in flight, or a push being waited on
  staleSince: () => number | null; // when gh started failing, while it still does: the rows are from before
  fetched: () => Run[] | null; // every run the last good poll listed, holds or not; null before the first
};

// Between polls only an expiring hold changes the band without counting up.
export const needsRedraw = (counting: boolean, shown: number, lastShown: number): boolean =>
  counting || shown !== lastShown;

export function createPoller(repo: string, deps: PollerDeps, config: PollerConfig = DEFAULT_CONFIG): Poller {
  let rows: Run[] = [];
  let fetched: Run[] | null = null;
  let pushedAt: number | null = null;
  let seen: ReadonlySet<number> = new Set();
  let firstPoll = true; // the first poll only learns what is already running, without notifying
  let staleSince: number | null = null; // the first failed poll of the current outage
  let timer: Timer | null = null;
  let polling = false; // one poll at a time: a wake mid-poll must not start a second chain of timers

  const waitingSince = (): number | null =>
    pushedAt !== null && deps.now() - pushedAt < config.watchMs ? pushedAt : null;
  const waiting = () => waitingSince() !== null;
  const live = () => rows.some(inFlight) || waiting();

  const fetchRuns = async (): Promise<Run[] | null> => {
    try {
      const [runs, prs] = await Promise.all([deps.listRuns(), deps.listPrs().catch(() => [] as Pr[])]);
      staleSince = null;
      return withPrs(runs.filter(startedByPerson), prs);
    } catch (error) {
      if (staleSince === null) deps.log(error instanceof Error ? error.message : String(error)); // one line per outage
      staleSince ??= deps.now();
      return null;
    }
  };

  const announce = (started: Run[], finished: Run[]) => {
    if (!firstPoll) for (const run of started) deps.toast(startedToast(repo, run));
    for (const toast of finishedToasts(repo, finished, deps.now())) deps.toast(toast.text, toast.timeoutMs);
    firstPoll = false;
  };

  const poll = async (): Promise<boolean> => {
    const runs = await fetchRuns();
    if (runs === null) return waiting();
    fetched = runs;

    const changes = transitions(seen, runs);
    seen = changes.seen;
    const since = pushedAt; // narrowed copy: TS resets `let` narrowing inside the callback
    if (since !== null && runs.some((run) => attemptStartedAt(run) >= since - CLOCK_SKEW_MS)) pushedAt = null; // the push's run, or rerun, is here
    announce(changes.started, changes.finished);
    rows = visible(runs, deps.now(), config);
    return live();
  };

  const loop = async () => {
    if (polling) return; // a wake during a poll: the running poll already sees pushedAt and keeps the active pace
    polling = true;
    const active = await poll()
      .then((pace) => {
        deps.onChange();
        return pace;
      })
      .catch((error: unknown) => {
        deps.log(error instanceof Error ? error.message : String(error));
        return waiting();
      })
      .finally(() => (polling = false));
    timer = deps.after(active ? config.activeMs : config.idleMs, () => void loop());
  };

  const pollNow = () => {
    timer?.cancel();
    timer = null;
    void loop();
  };

  return {
    start: () => void loop(),
    wake: () => {
      pushedAt = deps.now();
      deps.onChange();
      pollNow();
    },
    refresh: pollNow,
    rows: () => visible(rows, deps.now(), config), // the same rule on what the last poll kept, as time passes
    waitingSince,
    live,
    staleSince: () => staleSince,
    fetched: () => fetched,
  };
}

